-- 133 | 2026-11-21 | Can Tho OLD wave 3/3. Research lead only, NOT verified GPS/visits.
WITH src AS(SELECT x.*,md5('fbmn:cantho-old:wave03:'||x.source_key) dg
 FROM jsonb_to_recordset('[{"district":"Huyện Vĩnh Thạnh","name":"Nhà sách Hồng Phúc","address_line":"4032 QL80, xã Thạnh An cũ, huyện Vĩnh Thạnh","category":"nha_sach","phone":"02923856511","tax_code":null,"source_key":"gmap:ChIJy_ljVOOjoDER15fvYfnZyI0","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20H%E1%BB%93ng%20Ph%C3%BAc%204032%20QL80%2C%20x%C3%A3%20Th%E1%BA%A1nh%20An%20c%C5%A9%2C%20huy%E1%BB%87n%20V%C4%A9nh%20Th%E1%BA%A1nh%20C%E1%BA%A7n%20Th%C6%A1&query_place_id=ChIJy_ljVOOjoDER15fvYfnZyI0","verification_note":"Google Maps có địa điểm, chưa Sales ghé hoặc xác minh tồn tại và nhóm hàng năm 2026."},{"district":"Huyện Vĩnh Thạnh","name":"Hiệu sách Như Ngọc","address_line":"QL80, huyện Vĩnh Thạnh cũ (Plus Code 69JW+MQR)","category":"nha_sach","phone":"02926269131","tax_code":null,"source_key":"gmap:ChIJb9lMPxqgoDERKSRyCKQb7uo","source_url":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20Nh%C6%B0%20Ng%E1%BB%8Dc%20QL80%2C%20huy%E1%BB%87n%20V%C4%A9nh%20Th%E1%BA%A1nh%20c%C5%A9%20(Plus%20Code%2069JW%2BMQR)%20C%E1%BA%A7n%20Th%C6%A1&query_place_id=ChIJb9lMPxqgoDERKSRyCKQb7uo","verification_note":"Google Maps có địa điểm, chưa Sales ghé hoặc xác minh tồn tại và nhóm hàng năm 2026."},{"district":"Huyện Cờ Đỏ","name":"Nhà sách Minh Thư","address_line":"Ấp Thới Bình, thị trấn Cờ Đỏ cũ, huyện Cờ Đỏ","category":"nha_sach","phone":null,"tax_code":null,"source_key":"hongha:minhthu:thoibinh-codo","source_url":"https://vpphongha.com.vn/vi/gaga","verification_note":"Danh sách Hồng Hà nêu ấp Thới Bình, TT Cờ Đỏ, chưa có số nhà và số điện thoại."},{"district":"Huyện Thới Lai","name":"Nhà sách Thứ Hai - Công ty B.H","address_line":"Đường số 3, khu đô thị Cadif, thị trấn Thới Lai cũ, huyện Thới Lai","category":"nha_sach","phone":"0917577940","tax_code":null,"source_key":"gmap:ChIJMZFcSbGboDERNDxdGAE7RQ4","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Th%E1%BB%A9%20Hai%20-%20C%C3%B4ng%20ty%20B.H%20%C4%90%C6%B0%E1%BB%9Dng%20s%E1%BB%91%203%2C%20khu%20%C4%91%C3%B4%20th%E1%BB%8B%20Cadif%2C%20th%E1%BB%8B%20tr%E1%BA%A5n%20Th%E1%BB%9Bi%20Lai%20c%C5%A9%2C%20huy%E1%BB%87n%20Th%E1%BB%9Bi%20Lai%20C%E1%BA%A7n%20Th%C6%A1&query_place_id=ChIJMZFcSbGboDERNDxdGAE7RQ4","verification_note":"Google Maps có địa điểm, chưa Sales ghé hoặc xác minh tồn tại và nhóm hàng năm 2026."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,phone text,tax_code text,source_key text,source_url text,verification_note text)),
 ins AS(INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'Cần Thơ',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; tình trạng bán lẻ chưa Sales xác minh. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-can-tho-old-wave-03'
 FROM src s WHERE s.district IN ('Huyện Vĩnh Thạnh','Huyện Cờ Đỏ','Huyện Thới Lai') AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.province='Cần Thơ' AND c.district=s.district
 AND (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM public.field_prospects p WHERE p.province='Cần Thơ' AND p.district=s.district
 AND(p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone)
 SELECT district,count(*)::int inserted,count(*) FILTER(WHERE category='nha_sach')::int bookstores FROM ins GROUP BY district ORDER BY district;